// A store outage is not a reason to fail the turn the customer already received.
async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
  if (!store?.save) return;

  try {
    await store.save(session);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
  }
}

// Preserves the thrown Error instance or wraps any other rejection with itself as cause.
function toError(rejection: unknown): Error {
  if (rejection instanceof Error) return rejection;
  return new Error(describeRejection(rejection), {cause: rejection});
}

function describeRejection(rejection: unknown): string {
  if (typeof rejection === 'string') return rejection;
  if (typeof rejection === 'object' && rejection !== null) {
    try {
      return JSON.stringify(rejection) ?? String(rejection);
    } catch {
      return '[unserialisable object]';
    }
  }
  return String(rejection);
}

